void write_event_with_int(
    EventStreamProto& stream, EventType event_type, std::uint64_t time, DataType data_type, int value)
{
    auto event = stream.open_event(event_type, time);
    stream.add_int_data(event, data_type, value);
    stream.close_event(event);
}

void write_event_with_uint(
    EventStreamProto& stream, EventType event_type, std::uint64_t time, DataType data_type, std::uint64_t value)
{
    auto event = stream.open_event(event_type, time);
    stream.add_uint_data(event, data_type, value);
    stream.close_event(event);
}

void write_event_with_two_ints(EventStreamProto& stream,
                               EventType event_type,
                               std::uint64_t time,
                               DataType first_type,
                               int first_value,
                               DataType second_type,
                               int second_value)
{
    auto event = stream.open_event(event_type, time);
    stream.add_int_data(event, first_type, first_value);
    stream.add_int_data(event, second_type, second_value);
    stream.close_event(event);
}

void write_event_with_string(
    EventStreamProto& stream, EventType event_type, std::uint64_t time, DataType data_type, const std::string& value)
{
    auto event = stream.open_event(event_type, time);
    stream.add_string_data(event, data_type, value);
    stream.close_event(event);
}

void generate_read_stream(const fs::path& output, int events)
{
    EventStreamProto stream(output.string(), true);
    auto one = stream.define_event("one", "event");
    auto two = stream.define_event("two", "event");
    auto data1 = stream.define_data("data1", "data");
    auto data2 = stream.define_data("data2", "data");

    stream.set_int_parameter("core.machine_width", "machine width", 4);
    stream.set_json_parameter("core.scheduler_configuration", "scheduler configuration", "[7,4]");
    stream.start_simulation();

    for (int i = 0; i < events; ++i) {
        write_event_with_two_ints(stream, one, static_cast<std::uint64_t>(i * 20), data1, i % 64, data2, i % 1024);
        write_event_with_int(stream, two, static_cast<std::uint64_t>(i * 20 + 10), data1, i % 8);
    }
}

void generate_evp_stream(const fs::path& output, int events)
{
    EventStreamProto stream(output.string(), true);

    auto one = stream.define_event("one", "event");
    auto two = stream.define_event("two", "event");
    auto a = stream.define_event("a", "event");
    auto b = stream.define_event("b", "event");
    auto alloc = stream.define_event("alloc", "event");
    auto dealloc = stream.define_event("dealloc", "event");
    auto marker = stream.define_event("marker", "event");
    auto clock_skip = stream.define_event("clock_skip", "event");
    auto foo0 = stream.define_event("a_0.b_0.foo", "event");
    auto foo1 = stream.define_event("a_0.b_1.foo", "event");
    auto foo2 = stream.define_event("a_1.b_0.foo", "event");
    auto foo3 = stream.define_event("a_1.b_1.foo", "event");
    auto ev = stream.define_event("ev", "event");

    auto data1 = stream.define_data("data1", "data");
    auto data2 = stream.define_data("data2", "data");
    auto txid = stream.define_data("txid", "data");
    auto label = stream.define_data("label", "data");
    EnumMappingType enum_values{{1, "a"}, {2, "b"}, {3, "c"}};
    auto enum_type = stream.define_enum(0, enum_values);
    auto myenum = stream.define_data("myenum", "data", enum_type);

    stream.set_int_parameter("core.machine_width", "machine width", 4);
    stream.set_int_parameter("core.rob.size", "rob size", 192);
    stream.set_json_parameter("core.scheduler_configuration", "scheduler configuration", "[7,4]");
    stream.set_string_parameter("three", "three", "four");
    stream.start_simulation();

    for (int i = 0; i < events; ++i) {
        auto base_time = static_cast<std::uint64_t>(i * 100);
        write_event_with_two_ints(stream, one, base_time + 10, data1, i % 64, data2, i % 1024);
        write_event_with_two_ints(stream, two, base_time + 20, data1, (i + 1) % 64, data2, (i + 7) % 1024);
        write_event_with_uint(stream, a, base_time + 30, txid, static_cast<std::uint64_t>(i));
        write_event_with_uint(stream, b, base_time + 55, txid, static_cast<std::uint64_t>(i));

        stream.post_event(alloc, base_time + 60);
        if ((i % 3) != 0)
            stream.post_event(dealloc, base_time + 80);
        if ((i % 5) == 0)
            stream.post_event(marker, base_time + 85);
        if ((i % 16) == 0)
            stream.post_event(clock_skip, base_time + 90);

        stream.post_event(i % 4 == 0 ? foo0 : i % 4 == 1 ? foo1 : i % 4 == 2 ? foo2 : foo3, base_time + 92);

        auto enum_event = stream.open_event(ev, base_time + 95);
        stream.add_int_data(enum_event, myenum, (i % 3) + 1);
        stream.close_event(enum_event);

        if ((i % 8) == 0)
            write_event_with_string(stream, one, base_time + 99, label, fmt::format("label_{}", i % 4));
    }
}

void write_python_plugin(const fs::path& output)
{
    std::ofstream plugin{output};
    plugin << R"(import evp

seen = 0

def on_one(event):
    global seen
    seen += event.data.get("data1", 0)

def collect(_time):
    return {"python_seen": seen}

evp.on("one", on_one)
evp.collect(collect)
)";
}

const BenchmarkData& benchmark_data()
{
    static const BenchmarkData data = [] {
        BenchmarkData generated{.directory = BENCHMARK_DATA_DIRECTORY};
        fs::create_directories(generated.directory);
        generated.read_stream = generated.directory / "read.es";
        generated.compressed_read_stream = generated.directory / "read.es.xz";
        generated.evp_stream = generated.directory / "evp.es";
        generated.python_plugin = generated.directory / "python_plugin.py";

        generate_read_stream(generated.read_stream, kReadEvents);
        generate_read_stream(generated.compressed_read_stream, kReadEvents);
        generate_evp_stream(generated.evp_stream, kEvpEvents);
        write_python_plugin(generated.python_plugin);
        return generated;
    }();

    return data;
}

fs::path output_path(std::string_view name)
{
    return benchmark_data().directory / fmt::format("{}.out", name);
}

void read_all_records(const fs::path& stream_path)
{
    perf_streams::event_stream::EventStreamReader reader(stream_path);
    perf_streams::event_stream_proto::Record record;
    std::uint64_t records = 0;
    while (reader.read(record)) {
        ++records;
        record.Clear();
    }
    benchmark::DoNotOptimize(records);
}

void read_all_events(const fs::path& stream_path)
{
    perf_streams::event_stream::EventStreamReader reader(stream_path);
    std::uint64_t events = 0;
    while (reader.read_event()) {
        ++events;
    }
    benchmark::DoNotOptimize(events);
}

void read_included_events(const fs::path& stream_path)
{
    perf_streams::event_stream::EventStreamReader reader(stream_path);
    reader.include("one");
    std::uint64_t events = 0;
    while (reader.read_event()) {
        ++events;
    }
    benchmark::DoNotOptimize(events);
}

void run_checked_evp(const std::vector<std::string>& args, const fs::path& stdout_path, const fs::path& stderr_path)
{
    auto pid = fork();
    if (pid < 0)
        throw std::runtime_error{fmt::format("fork failed: {}", std::strerror(errno))};

    if (pid == 0) {
        auto stdout_fd = open(stdout_path.c_str(), O_CREAT | O_WRONLY | O_TRUNC, 0600);
        auto stderr_fd = open(stderr_path.c_str(), O_CREAT | O_WRONLY | O_TRUNC, 0600);
        if (stdout_fd < 0 || stderr_fd < 0)
            _exit(127);
        if (dup2(stdout_fd, STDOUT_FILENO) < 0 || dup2(stderr_fd, STDERR_FILENO) < 0)
            _exit(127);
        close(stdout_fd);
        close(stderr_fd);

        std::vector<std::string> argv_storage;
        argv_storage.reserve(args.size() + 1);
        argv_storage.emplace_back(EVP_PROGRAM);
        argv_storage.insert(argv_storage.end(), args.begin(), args.end());

        std::vector<char*> argv;
        argv.reserve(argv_storage.size() + 1);
        for (auto& arg : argv_storage)
            argv.push_back(arg.data());
        argv.push_back(nullptr);

        execv(argv[0], argv.data());
        _exit(127);
    }

    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno != EINTR)
            throw std::runtime_error{fmt::format("waitpid failed: {}", std::strerror(errno))};
    }

    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0)
        throw std::runtime_error{fmt::format("evp exited with status {}", status)};
}

void run_evp_benchmark(benchmark::State& state, const std::vector<std::string>& args, std::string_view name)
{
    auto stdout_path = output_path(fmt::format("{}-stdout", name));
    auto stderr_path = output_path(fmt::format("{}-stderr", name));

    try {
        for (auto _ : state)
            run_checked_evp(args, stdout_path, stderr_path);
    } catch (const std::exception& err) {
        state.SkipWithError(err.what());
    }
}

