void BM_EventStreamWriteBareEvents(benchmark::State& state)
{
    auto path = output_path("write-bare.es");
    for (auto _ : state) {
        EventStreamProto stream(path.string(), true);
        auto event_type = stream.define_event("bare", "event");
        stream.start_simulation();
        for (int i = 0; i < state.range(0); ++i)
            stream.post_event(event_type, static_cast<std::uint64_t>(i));
    }
    state.SetItemsProcessed(state.iterations() * state.range(0));
}

void BM_EventStreamWriteIntegerData(benchmark::State& state)
{
    auto path = output_path("write-integer.es");
    for (auto _ : state) {
        EventStreamProto stream(path.string(), true);
        auto event_type = stream.define_event("with_int", "event");
        auto data_type = stream.define_data("value", "data");
        stream.start_simulation();
        for (int i = 0; i < state.range(0); ++i)
            write_event_with_int(stream, event_type, static_cast<std::uint64_t>(i), data_type, i);
    }
    state.SetItemsProcessed(state.iterations() * state.range(0));
}

void BM_EventStreamWriteMixedData(benchmark::State& state)
{
    auto path = output_path("write-mixed.es");
    for (auto _ : state) {
        EventStreamProto stream(path.string(), true);
        auto event_type = stream.define_event("with_mixed_data", "event");
        auto int_data = stream.define_data("value", "data");
        auto string_data = stream.define_data("label", "data");
        stream.start_simulation();
        for (int i = 0; i < state.range(0); ++i) {
            auto event = stream.open_event(event_type, static_cast<std::uint64_t>(i));
            stream.add_int_data(event, int_data, i);
            stream.add_string_data(event, string_data, fmt::format("label_{}", i % 16));
            stream.close_event(event);
        }
    }
    state.SetItemsProcessed(state.iterations() * state.range(0));
}

